-- S22-AT: CAMBIO v2, juicio independiente y cobertura.
BEGIN;
INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion) VALUES('at_catalog_source_wrong','boolean','ninguna','at_catalog_source_wrong; hecho derivado del catálogo gobernado, binding runtime pendiente');
INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen) VALUES('FIELDS','at_catalog_source_wrong','CURADO') ON CONFLICT DO NOTHING;
INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion) VALUES('at_inactive_country_visible','boolean','ninguna','at_inactive_country_visible; hecho derivado del catálogo gobernado, binding runtime pendiente');
INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen) VALUES('FIELDS','at_inactive_country_visible','CURADO') ON CONFLICT DO NOTHING;
INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion) VALUES('at_location_fallback_not_pe','boolean','ninguna','at_location_fallback_not_pe; hecho derivado del catálogo gobernado, binding runtime pendiente');
INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen) VALUES('FIELDS','at_location_fallback_not_pe','CURADO') ON CONFLICT DO NOTHING;
DO $at$
DECLARE expected_delta bigint; packs jsonb := $pack$[{"codigo":"S22AP-484-1","legacy_id":484,"version_nucleo":2,"relacionadas":["S22M-C04"],"coberturas":[{"legacy_id":484,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Catálogo físico lf_ops.paises desplegado PR #4816: PE +51 prioritario, activos y orden alfabético; fallback Perú decidido. Sustituye bloqueo histórico por falta de catálogo; binding runtime pendiente."}],"paquete":{"modo":"HEREDA","tipo":"CAMBIO","clase":"PANTALLA","clave":"s22ap_legacy_484_0","dueno":"PRODUCTO","codigo":"S22AP-484-1","efecto":"BLOQUEAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/484","solicitante":"Cristhian / Claude S22-AT"},"titulo":"Prefijo visible +51 en ONB_001","alcance":"CLIENT_ONBOARDING","familia":"FIELDS","impacto":"REVISAR","autoridad":"LEG-PRODUCTO","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"ap_onb001_country_selector"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"ap_pe_not_first"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"ap_other_countries_not_alphabetical"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ap_location_preselection_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ap_prefix_not_canonical"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ap_chevron_missing_or_wrong_token"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ap_unregistered_country_option"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ap_selector_enabled_without_catalog"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"at_catalog_source_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"at_inactive_country_visible"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"at_location_fallback_not_pe"},"der":{"lit":true}}}},"naturaleza":"CONDUCTA","descripcion":"En ONB_001 BLOQUEAR selector cuyo catálogo no se resuelva desde lf_ops.paises, que muestre países inactivos o no ordene activos por es_prioritario DESC, orden_alfabetico ASC. Perú PE primero; preseleccionar país activo según ubicación cuando esté disponible y sea reconocida, en caso contrario fallback Perú PE. Prefijo visible desde prefijo_telefonico del país seleccionado; Perú resuelve +51 desde tabla, no hardcodear prefijo ni inventar opciones. Chevron pequeño visible navy_muted, no azul; selector dropdown permite solo opciones activas registradas. Si catálogo no disponible no habilitar opciones inventadas. No modifica IG ni rasters; binding runtime pendiente.","pruebas":[{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":true,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":true,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":true,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":true,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":true,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":true,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":true,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":true,"at_inactive_country_visible":false,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":true,"at_location_fallback_not_pe":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":true,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":true},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ap_onb001_country_selector":false,"ap_pe_not_first":false,"ap_other_countries_not_alphabetical":false,"ap_location_preselection_wrong":false,"ap_prefix_not_canonical":false,"ap_chevron_missing_or_wrong_token":false,"ap_unregistered_country_option":false,"ap_selector_enabled_without_catalog":false,"at_catalog_source_wrong":false,"at_inactive_country_visible":false,"at_location_fallback_not_pe":true},"esperado":false,"casuistica":"NO_SE_CUMPLE"}]},"hash_paquete":"cb38a4192e9992b8da74275a9dc384d8aa1f4c669a2857edb6ab4cd7aeafbfb6","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb; v integer;
BEGIN
 IF (SELECT count(*) FROM lf_ops.reglas)=586 THEN
 IF NOT EXISTS (SELECT 1 FROM lf_ops.paises WHERE iso2='PE' AND prefijo_telefonico='+51' AND activo AND es_prioritario) OR (SELECT iso2 FROM lf_ops.paises WHERE activo ORDER BY es_prioritario DESC,orden_alfabetico LIMIT 1) IS DISTINCT FROM 'PE' THEN RAISE EXCEPTION 'S22AT_COUNTRY_PREFLIGHT'; END IF;
 END IF;
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT count(DISTINCT (cv.coverage->>'legacy_id')::bigint) INTO expected_delta FROM jsonb_array_elements(packs) AS pk(package) CROSS JOIN LATERAL jsonb_array_elements(pk.package->'coberturas') AS cv(coverage) WHERE cv.coverage->>'estado_cobertura'='REEMPLAZADA' AND NOT EXISTS (SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada AS existing_cov WHERE existing_cov.legacy_id=(cv.coverage->>'legacy_id')::bigint AND existing_cov.estado_cobertura='REEMPLAZADA');
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo'; v:=(p->>'version_nucleo')::int;
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM v THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,v);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=v LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','Claude 2026-11-26 07:42 Lima: Revisado conforme; S22AP-484-1 CAMBIO v2, 484 reemplazada sin residual; juicio V3 independiente');
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22AT_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22AT_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=v AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22AT_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>jsonb_array_length(packs) OR vectors<>(SELECT coalesce(sum(jsonb_array_length(value->'paquete'->'pruebas')),0) FROM jsonb_array_elements(packs)) THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; v:=(p->>'version_nucleo')::int; h:=lf_ops.nucleo_hash_paquete_v1(cd,v);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22AT_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR c->>'estado_cobertura' NOT IN ('REEMPLAZADA','PARCIAL') OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') OR (c->>'estado_cobertura'='PARCIAL' AND coalesce(length(residual),0)<15) THEN RAISE EXCEPTION 'S22AT_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,v,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-26 07:42 Lima'),h,'GPT / Claude S22-AT independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22AT_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>(SELECT coalesce(sum(jsonb_array_length(value->'coberturas')),0) FROM jsonb_array_elements(packs)) OR after_replaced<>before_replaced+expected_delta) THEN RAISE EXCEPTION 'S22AT_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22AT_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22AT_PASS JUICIOS=% AUTO=% VECTORES=% links=% replaced=% DPIG03=0',n,n,vectors,links,after_replaced;
END $at$;
COMMIT;
